from collections import Counter

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Find separator color (color that forms at least one full row or full column)
    sep_color = None
    for c in range(10):
        has_full_row = any(all(grid[r][k] == c for k in range(cols)) for r in range(rows))
        has_full_col = any(all(grid[r][k] == c for r in range(rows)) for k in range(cols))
        if has_full_row or has_full_col:
            sep_color = c
            break

    # Identify separator row and column indices
    sep_rows = set(r for r in range(rows) if all(grid[r][k] == sep_color for k in range(cols)))
    sep_cols = set(k for k in range(cols) if all(grid[r][k] == sep_color for r in range(rows)))

    # Group non-separator indices into contiguous regions
    row_groups = []
    current = []
    for r in range(rows):
        if r in sep_rows:
            if current:
                row_groups.append(current)
                current = []
        else:
            current.append(r)
    if current:
        row_groups.append(current)

    col_groups = []
    current = []
    for k in range(cols):
        if k in sep_cols:
            if current:
                col_groups.append(current)
                current = []
        else:
            current.append(k)
    if current:
        col_groups.append(current)

    # Initialize output grid as copy of input
    output = [row[:] for row in grid]

    # Process each region
    for rng_rows in row_groups:
        for rng_cols in col_groups:
            # Collect all values in the region
            values = []
            for r in rng_rows:
                for k in rng_cols:
                    values.append(grid[r][k])

            if not values:
                continue

            # Count occurrences of each color
            cnt = Counter(values)

            # Determine fill color based on density
            if len(cnt) == 1:
                # Single color region - keep same color
                fill_color = list(cnt.keys())[0]
            else:
                # Multiple colors - find minority
                sorted_items = sorted(cnt.items(), key=lambda x: x[1], reverse=True)
                majority_val = sorted_items[0][0]
                minority_val = sorted_items[1][0]
                minority_count = sorted_items[1][1]
                area = len(rng_rows) * len(rng_cols)

                # Fill with minority if minority_count * 4 >= area (density >= 25%)
                if minority_count * 4 >= area:
                    fill_color = minority_val
                else:
                    fill_color = majority_val

            # Apply fill color to entire region
            for r in rng_rows:
                for k in rng_cols:
                    output[r][k] = fill_color

    return output
